contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address addr) public payable {
        require(addr != address(0), "zero address");

        uint256 cBalanceBefore = address(c).balance;
        uint256 addrBalanceBefore = c.balances(addr); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 addrBalanceAfter = c.balances(addr); if (__ESBMC_reverted()) return;

        assert(!reverted && cBalanceBefore == cBalanceAfter && addrBalanceBefore == 0 && addrBalanceAfter == 0);
    }

    receive() external payable {}
}

